impl IterableAttrs<'_> {
    pub fn lookup_attr(
        &self,
        offset: usize,
        missing_type: Option<u16>,
    ) -> (Vec<(&'static str, usize)>, Option<&'static str>) {
        let mut stack = Vec::new();
        let cur = ErrorContext::calc_offset(self.orig_loc, self.buf.as_ptr() as usize);
        if missing_type.is_some() && cur == offset {
            stack.push(("Attrs", offset));
            return (stack, missing_type.and_then(|t| Attrs::attr_from_type(t)));
        }
        if cur > offset || cur + self.buf.len() < offset {
            return (stack, None);
        }
        let mut attrs = self.clone();
        let mut last_off = cur + attrs.pos;
        let mut missing = None;
        while let Some(attr) = attrs.next() {
            let Ok(attr) = attr else { break };
            match attr {
                Attrs::Kind(val) => {
                    if last_off == offset {
                        stack.push(("Kind", last_off));
                        break;
                    }
                }
                Attrs::Options(val) => {
                    if last_off == offset {
                        stack.push(("Options", last_off));
                        break;
                    }
                }
                Attrs::Stats(val) => {
                    if last_off == offset {
                        stack.push(("Stats", last_off));
                        break;
                    }
                }
                Attrs::Xstats(val) => {
                    if last_off == offset {
                        stack.push(("Xstats", last_off));
                        break;
                    }
                }
                Attrs::Rate(val) => {
                    if last_off == offset {
                        stack.push(("Rate", last_off));
                        break;
                    }
                }
                Attrs::Fcnt(val) => {
                    if last_off == offset {
                        stack.push(("Fcnt", last_off));
                        break;
                    }
                }
                Attrs::Stats2(val) => {
                    (stack, missing) = val.lookup_attr(offset, missing_type);
                    if !stack.is_empty() {
                        break;
                    }
                }
                Attrs::Stab(val) => {
                    (stack, missing) = val.lookup_attr(offset, missing_type);
                    if !stack.is_empty() {
                        break;
                    }
                }
                Attrs::Pad(val) => {
                    if last_off == offset {
                        stack.push(("Pad", last_off));
                        break;
                    }
                }
                Attrs::DumpInvisible(val) => {
                    if last_off == offset {
                        stack.push(("DumpInvisible", last_off));
                        break;
                    }
                }
                Attrs::Chain(val) => {
                    if last_off == offset {
                        stack.push(("Chain", last_off));
                        break;
                    }
                }
                Attrs::HwOffload(val) => {
                    if last_off == offset {
                        stack.push(("HwOffload", last_off));
                        break;
                    }
                }
                Attrs::IngressBlock(val) => {
                    if last_off == offset {
                        stack.push(("IngressBlock", last_off));
                        break;
                    }
                }
                Attrs::EgressBlock(val) => {
                    if last_off == offset {
                        stack.push(("EgressBlock", last_off));
                        break;
                    }
                }
                Attrs::DumpFlags(val) => {
                    if last_off == offset {
                        stack.push(("DumpFlags", last_off));
                        break;
                    }
                }
                Attrs::ExtWarnMsg(val) => {
                    if last_off == offset {
                        stack.push(("ExtWarnMsg", last_off));
                        break;
                    }
                }
                _ => {}
            };
            last_off = cur + attrs.pos;
        }
        if !stack.is_empty() {
            stack.push(("Attrs", cur));
        }
        (stack, missing)
    }
}
