impl IterableBpfAttrs<'_> {
    pub fn lookup_attr(
        &self,
        offset: usize,
        missing_type: Option<u16>,
    ) -> (Vec<(&'static str, usize)>, Option<&'static str>) {
        let mut stack = Vec::new();
        let cur = ErrorContext::calc_offset(self.orig_loc, self.buf.as_ptr() as usize);
        if missing_type.is_some() && cur == offset {
            stack.push(("BpfAttrs", offset));
            return (
                stack,
                missing_type.and_then(|t| BpfAttrs::attr_from_type(t)),
            );
        }
        if cur > offset || cur + self.buf.len() < offset {
            return (stack, None);
        }
        let mut attrs = self.clone();
        let mut last_off = cur + attrs.pos;
        let mut missing = None;
        while let Some(attr) = attrs.next() {
            let Ok(attr) = attr else { break };
            match attr {
                BpfAttrs::Act(val) => {
                    for entry in val {
                        let Ok(attr) = entry else { break };
                        (stack, missing) = attr.lookup_attr(offset, missing_type);
                        if !stack.is_empty() {
                            break;
                        }
                    }
                    if !stack.is_empty() {
                        stack.push(("Act", last_off));
                        break;
                    }
                }
                BpfAttrs::Police(val) => {
                    (stack, missing) = val.lookup_attr(offset, missing_type);
                    if !stack.is_empty() {
                        break;
                    }
                }
                BpfAttrs::Classid(val) => {
                    if last_off == offset {
                        stack.push(("Classid", last_off));
                        break;
                    }
                }
                BpfAttrs::OpsLen(val) => {
                    if last_off == offset {
                        stack.push(("OpsLen", last_off));
                        break;
                    }
                }
                BpfAttrs::Ops(val) => {
                    if last_off == offset {
                        stack.push(("Ops", last_off));
                        break;
                    }
                }
                BpfAttrs::Fd(val) => {
                    if last_off == offset {
                        stack.push(("Fd", last_off));
                        break;
                    }
                }
                BpfAttrs::Name(val) => {
                    if last_off == offset {
                        stack.push(("Name", last_off));
                        break;
                    }
                }
                BpfAttrs::Flags(val) => {
                    if last_off == offset {
                        stack.push(("Flags", last_off));
                        break;
                    }
                }
                BpfAttrs::FlagsGen(val) => {
                    if last_off == offset {
                        stack.push(("FlagsGen", last_off));
                        break;
                    }
                }
                BpfAttrs::Tag(val) => {
                    if last_off == offset {
                        stack.push(("Tag", last_off));
                        break;
                    }
                }
                BpfAttrs::Id(val) => {
                    if last_off == offset {
                        stack.push(("Id", last_off));
                        break;
                    }
                }
                _ => {}
            };
            last_off = cur + attrs.pos;
        }
        if !stack.is_empty() {
            stack.push(("BpfAttrs", cur));
        }
        (stack, missing)
    }
}
